package Assignments;

public class Nested_If {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		int a = 30;
		int b = 20;
		int c = 99;

		if (a>= b) {
			if (a>= c) {
				System.out.println("1");
			} else {
				System.out.println("2");
			}
		} else {

				System.out.println("3");
			}
		}

	}
